//go:build unix

package ca

import (
	"bytes"
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/x509"
	"errors"
	"fmt"
)

// validateCAProfile accepts the crypto and extension profile generated by newCA,
// not arbitrary signing CAs. Matching this profile does not prove provenance.
// The caller separately verifies the signature, key pairing, and validity window.
func validateCAProfile(cert *x509.Certificate) error {
	if cert.Version != 3 {
		return errors.New("CA certificate must use X.509 version 3")
	}
	if cert.SignatureAlgorithm != x509.ECDSAWithSHA256 {
		return errors.New("CA signature algorithm must be ECDSA-SHA256")
	}

	key, ok := cert.PublicKey.(*ecdsa.PublicKey)
	if !ok || key.Curve != elliptic.P256() {
		return errors.New("CA public key must be ECDSA P-256")
	}

	if !bytes.Equal(cert.RawIssuer, cert.RawSubject) {
		return errors.New("CA certificate must be self-issued")
	}

	if !cert.IsCA || !cert.BasicConstraintsValid {
		return errors.New("CA basic constraints must identify a CA")
	}
	if cert.MaxPathLen != -1 || cert.MaxPathLenZero {
		return errors.New("CA path length must be unconstrained")
	}
	if cert.KeyUsage != caKeyUsage {
		return errors.New("CA key usage must match the generated profile")
	}
	if len(cert.UnhandledCriticalExtensions) != 0 {
		return fmt.Errorf("CA certificate has unhandled critical extensions: %v", cert.UnhandledCriticalExtensions)
	}

	// ParseCertificate rejects duplicate extension OIDs. Allowing only these
	// three and requiring all three excludes constraints and optional extensions
	// that this issuer does not support, even when marked non-critical.
	for _, ext := range cert.Extensions {
		var critical bool
		switch ext.Id.String() {
		case "2.5.29.15", "2.5.29.19": // key usage, basic constraints
			critical = true
		case "2.5.29.14": // subject key identifier
		default:
			return fmt.Errorf("unsupported CA extension %s", ext.Id)
		}
		if ext.Critical != critical {
			return fmt.Errorf("CA extension %s must have critical=%t", ext.Id, critical)
		}
	}
	if len(cert.Extensions) != 3 {
		return errors.New("CA certificate must contain key usage, basic constraints, and subject key identifier extensions")
	}
	if len(cert.SubjectKeyId) != 20 {
		return errors.New("CA subject key identifier must be 20 bytes")
	}

	return nil
}
